/* Guard rule as per specification */
[hidden] {
  display: none !important;
}

:root {
  --bg-color: #2b2d42;
  --meter-metal: #8d99ae;
  --meter-dark: #4b5366;
  --meter-shadow: #212529;
  --screen-bg-active: #a7c957;
  --screen-text-active: #1a4314;
  --screen-bg-expired: #d90429;
  --screen-text-expired: #ffffff;
  --btn-bg: #edf2f4;
  --btn-text: #2b2d42;
  --btn-danger-bg: #ef233c;
  --btn-danger-text: #ffffff;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  background-color: var(--bg-color);
  font-family: 'Courier New', Courier, monospace;
  font-size: 16px;
  display: flex;
  justify-content: center;
  align-items: center;
  padding: 24px 16px;
  color: #edf2f4;
}

.meter-container {
  display: flex;
  flex-direction: column;
  align-items: center;
  width: 100%;
  max-width: 380px;
}

.meter-cap {
  width: 160px;
  height: 24px;
  background-color: var(--meter-metal);
  border: 4px solid #111;
  border-bottom: none;
  box-shadow: inset -4px 0 0 var(--meter-shadow);
  display: flex;
  justify-content: center;
  align-items: center;
}

.coin-slot {
  width: 50px;
  height: 6px;
  background-color: #111;
}

.meter-body {
  width: 100%;
  background-color: var(--meter-metal);
  border: 4px solid #111;
  border-radius: 12px 12px 20px 20px;
  box-shadow:
    inset -6px -6px 0 var(--meter-shadow),
    inset 6px 6px 0 #b0bac9,
    0 12px 0 rgba(0, 0, 0, 0.4);
  padding: 24px 20px;
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.screen-frame {
  background-color: #1b1e23;
  padding: 12px;
  border: 4px solid #111;
  border-radius: 6px;
  box-shadow: inset 0 4px 0 rgba(0, 0, 0, 0.6);
}

.screen {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 16px 8px;
  min-height: 110px;
  border: 3px solid #111;
  text-align: center;
  transition: background-color 0.15s ease, color 0.15s ease;
}

.screen.active {
  background-color: var(--screen-bg-active);
  color: var(--screen-text-active);
}

.screen.expired {
  background-color: var(--screen-bg-expired);
  color: var(--screen-text-expired);
  animation: pulse-border 1.2s infinite alternate;
}

@keyframes pulse-border {
  from {
    filter: brightness(1);
  }
  to {
    filter: brightness(1.15);
  }
}

.badge {
  font-size: 1rem;
  font-weight: 900;
  letter-spacing: 2px;
  text-transform: uppercase;
  margin-bottom: 6px;
}

.time-text {
  font-size: 2.2rem;
  font-weight: bold;
  letter-spacing: 2px;
  line-height: 1.1;
}

.meter-instruction {
  font-size: 0.85rem;
  text-align: center;
  font-weight: bold;
  letter-spacing: 1px;
  color: #1b1e23;
}

.controls {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.pixel-btn {
  font-family: inherit;
  font-size: 1.05rem;
  font-weight: 800;
  padding: 12px 16px;
  background-color: var(--btn-bg);
  color: var(--btn-text);
  border: 3px solid #111;
  border-radius: 4px;
  cursor: pointer;
  box-shadow:
    0 4px 0 #111,
    inset -2px -2px 0 #bdc3c7,
    inset 2px 2px 0 #ffffff;
  text-transform: uppercase;
  letter-spacing: 1px;
  transition: transform 0.05s ease, box-shadow 0.05s ease;
}

.pixel-btn:hover {
  background-color: #ffffff;
}

.pixel-btn:focus-visible {
  outline: 3px dashed #fff;
  outline-offset: 3px;
}

.pixel-btn:active {
  transform: translateY(4px);
  box-shadow:
    0 0 0 #111,
    inset 2px 2px 0 rgba(0, 0, 0, 0.2);
}

.pixel-btn.btn-danger {
  background-color: var(--btn-danger-bg);
  color: var(--btn-danger-text);
  box-shadow:
    0 4px 0 #111,
    inset -2px -2px 0 #9b001a,
    inset 2px 2px 0 #ff758f;
}

.pixel-btn.btn-danger:hover {
  background-color: #ff334b;
}

.meter-pole {
  width: 48px;
  height: 70px;
  background-color: #555e6d;
  border: 4px solid #111;
  border-top: none;
  box-shadow: inset -6px 0 0 #393f49;
}

@media (min-width: 400px) {
  .meter-body {
    padding: 28px 24px;
  }
}

document.addEventListener('DOMContentLoaded', () => {
  let remainingSeconds = 0;
  let timerInterval = null;

  const screenEl = document.getElementById('meter-screen');
  const statusBadgeEl = document.getElementById('status-badge');
  const timeDisplayEl = document.getElementById('time-display');
  const btnAdd15 = document.getElementById('btn-add-15');
  const btnAdd60 = document.getElementById('btn-add-60');
  const btnReset = document.getElementById('btn-reset');

  function formatTime(totalSeconds) {
    const hours = Math.floor(totalSeconds / 3600);
    const minutes = Math.floor((totalSeconds % 3600) / 60);
    const seconds = totalSeconds % 60;

    const paddedMinutes = String(minutes).padStart(2, '0');
    const paddedSeconds = String(seconds).padStart(2, '0');

    return `${hours}:${paddedMinutes}:${paddedSeconds}`;
  }

  function updateDisplay() {
    if (remainingSeconds <= 0) {
      remainingSeconds = 0;
      screenEl.classList.remove('active');
      screenEl.classList.add('expired');
      statusBadgeEl.textContent = 'EXPIRED';
      timeDisplayEl.textContent = '0:00:00';
      stopTimer();
    } else {
      screenEl.classList.remove('expired');
      screenEl.classList.add('active');
      statusBadgeEl.textContent = 'PARKED';
      timeDisplayEl.textContent = formatTime(remainingSeconds);
    }
  }

  function tick() {
    if (remainingSeconds > 0) {
      remainingSeconds -= 1;
      updateDisplay();
    } else {
      stopTimer();
    }
  }

  function startTimer() {
    if (!timerInterval) {
      timerInterval = setInterval(tick, 1000);
    }
  }

  function stopTimer() {
    if (timerInterval) {
      clearInterval(timerInterval);
      timerInterval = null;
    }
  }

  function addTime(seconds) {
    remainingSeconds += seconds;
    updateDisplay();
    startTimer();
  }

  function reset() {
    stopTimer();
    remainingSeconds = 0;
    updateDisplay();
  }

  btnAdd15.addEventListener('click', () => {
    addTime(15 * 60);
  });

  btnAdd60.addEventListener('click', () => {
    addTime(60 * 60);
  });

  btnReset.addEventListener('click', () => {
    reset();
  });

  updateDisplay();
});
